"""
title: Jira Agent for Open-WebUI
description: A comprehensive tool for interacting with Jira - search, view, create, and comment on issues with ease. Supports OAuth 2.0 (3LO), PAT, and basic auth.
repository: https://github.com/taylorwilsdon/open-webui-tools
author: @taylorwilsdon
author_url: https://github.com/taylorwilsdon
version: 1.0.3
changelog:
  - 1.0.3: Add OAuth 2.0 support (3LO) - automatic token usage if available
  - 1.0.2: Add OpenAI-assisted project-name matching; fuzzy matching; project/search; valves include openai_api_key
  - 1.0.1: Update with PAT support
  - 1.0.0: Initial release with comprehensive Jira integration capabilities
"""

import json
import re
from typing import Any, Awaitable, Callable, Dict, Optional, List
import requests
from pydantic import BaseModel, Field, validator
import difflib

# ---- Optional OpenAI dependency (used only if key present) ----
try:
    import openai  # pip install openai

    _OPENAI_AVAILABLE = True
except Exception:
    _OPENAI_AVAILABLE = False

# ---- OAuth 2.0 Support (optional) ----
try:
    # Import depuis le module de stockage OAuth (disponible dans l'environnement OpenWebUI)
    import sys
    import os
    # Le backend est accessible depuis le contexte d'exécution du Tool
    try:
        from open_webui.utils.jira_oauth import get_user_oauth_token
        _OAUTH_AVAILABLE = True
    except ImportError:
        # Fallback: essayer avec le chemin absolu
        backend_path = os.path.join(os.path.dirname(__file__), '..', '..', 'backend')
        if os.path.exists(backend_path) and backend_path not in sys.path:
            sys.path.insert(0, backend_path)
        try:
            from open_webui.utils.jira_oauth import get_user_oauth_token
            _OAUTH_AVAILABLE = True
        except ImportError:
            _OAUTH_AVAILABLE = False
            get_user_oauth_token = None
except Exception:
    _OAUTH_AVAILABLE = False
    get_user_oauth_token = None



class EventEmitter:
    def __init__(self, event_emitter: Callable[[dict], Awaitable[None]]):
        self.event_emitter = event_emitter

    async def emit_status(
        self, description: str, done: bool, error: bool = False
    ) -> None:
        if error and not done:
            raise ValueError("Error status must also be marked as done")
        icon = "✅" if done and not error else "🚫 " if error else "💬"
        try:
            await self.event_emitter(
                {
                    "data": {
                        "description": f"{icon} {description}",
                        "status": "complete" if done else "in_progress",
                        "done": done,
                    },
                    "type": "status",
                }
            )
        except Exception as e:
            raise RuntimeError(f"Failed to emit status event: {str(e)}") from e

    async def emit_message(self, content: str) -> None:
        if not content:
            raise ValueError("Message content cannot be empty")
        try:
            await self.event_emitter({"data": {"content": content}, "type": "message"})
        except Exception as e:
            raise RuntimeError(f"Failed to emit message event: {str(e)}") from e

    async def emit_source(
        self, name: str, url: str, content: str, html: bool = False
    ) -> None:
        if not name or not url or not content:
            raise ValueError("Source name, URL, and content are required")
        try:
            await self.event_emitter(
                {
                    "type": "citation",
                    "data": {
                        "document": [content],
                        "metadata": [{"source": url, "html": html}],
                        "source": {"name": name},
                    },
                }
            )
        except Exception as e:
            raise RuntimeError(f"Failed to emit source event: {str(e)}") from e

    async def emit_table(
        self,
        headers: List[str],
        rows: List[List[Any]],
        title: Optional[str] = "Results",
    ) -> None:
        if not headers:
            raise ValueError("Table must have at least one header")
        if any(len(row) != len(headers) for row in rows):
            raise ValueError("All rows must have the same number of columns as headers")
        table = (
            f"### {title}\n\n|"
            + "|".join(headers)
            + "|\n|"
            + "|".join(["---"] * len(headers))
            + "|\n"
        )
        for row in rows:
            formatted_row = [str(cell).replace("|", "\\|") for cell in row]
            table += "|" + "|".join(formatted_row) + "|\n"
        table += "\n"
        await self.emit_message(table)


class JiraApiError(Exception):
    pass


class Jira:
    def __init__(
        self,
        username: str,
        password: str,
        base_url: str,
        pat: str = "",
        openai_api_key: str = "",
        oauth_token: Optional[str] = None,
    ):
        self.base_url = base_url.rstrip("/")
        self.username = username
        self.password = password
        self.pat = pat
        self.openai_api_key = openai_api_key or ""
        self.oauth_token = oauth_token
        self.headers = {
            "Accept": "application/json",
            "Content-Type": "application/json",
        }
        # Priorité: OAuth > PAT > username/password
        if self.oauth_token:
            self.headers["Authorization"] = f"Bearer {self.oauth_token}"
        elif (not self.username or not self.password) and self.pat:
            self.headers["Authorization"] = f"Bearer {self.pat}"
        self.api_version = "3"
        self._use_openai = bool(self.openai_api_key and _OPENAI_AVAILABLE)
        if self._use_openai:
            openai.api_key = self.openai_api_key

    def _get_auth(self):
        if self.username and self.password:
            return (self.username, self.password)
        return None

    def _handle_response(self, response: requests.Response, operation: str):
        if 200 <= response.status_code < 300:
            if response.content:
                return response.json()
            return {}
        error_msg = f"Jira API error ({response.status_code}): {response.text}"
        if response.status_code == 401:
            error_msg = "Authentication failed. Please check your username and API key."
        elif response.status_code == 403:
            error_msg = (
                "Permission denied. Either the PAT lacks required scopes (e.g., read:jira-work) "
                "or the user linked to this PAT lacks 'Browse Projects' permission for the target project, "
                "or issue-level security hides results. Verify scopes and project permissions, and confirm you're using /rest/api/3/search."
            )
        elif response.status_code == 404:
            error_msg = f"Resource not found while attempting to {operation}."
        raise JiraApiError(error_msg)

    # ---------- HTTP ----------
    def get(self, endpoint: str, params: Dict[str, Any] = None):
        url = f"{self.base_url}/rest/api/{self.api_version}/{endpoint}"
        response = requests.get(
            url, params=params, headers=self.headers, auth=self._get_auth()
        )
        return self._handle_response(response, f"get {endpoint}")

    def post(self, endpoint: str, data: Dict[str, Any]):
        url = f"{self.base_url}/rest/api/{self.api_version}/{endpoint}"
        response = requests.post(
            url, json=data, headers=self.headers, auth=self._get_auth()
        )
        return self._handle_response(response, f"post to {endpoint}")

    def put(self, endpoint: str, data: Dict[str, Any]):
        url = f"{self.base_url}/rest/api/{self.api_version}/{endpoint}"
        response = requests.put(
            url, json=data, headers=self.headers, auth=self._get_auth()
        )
        return self._handle_response(response, f"update {endpoint}")

    # ---------- Directory ----------
    def search_users(self, query: str, max_results: int = 25) -> List[Dict[str, str]]:
        url = f"{self.base_url}/rest/api/3/user/search"
        resp = requests.get(
            url,
            params={"query": query, "maxResults": max_results},
            headers=self.headers,
            auth=self._get_auth(),
        )
        data = self._handle_response(resp, f"search users '{query}'")
        exact = [u for u in data if u.get("displayName", "").lower() == query.lower()]
        candidates = exact if exact else data
        return [
            {
                "accountId": u.get("accountId", ""),
                "displayName": u.get("displayName", ""),
            }
            for u in candidates
        ]

    def search_projects(
        self, query: str = "", max_results: int = 1000
    ) -> List[Dict[str, str]]:
        url = f"{self.base_url}/rest/api/3/project/search"
        resp = requests.get(
            url,
            params={"query": query, "maxResults": max_results},
            headers=self.headers,
            auth=self._get_auth(),
        )
        data = self._handle_response(resp, "search projects")
        values = data.get("values", [])
        return [
            {
                "key": p.get("key", ""),
                "name": p.get("name", ""),
                "id": str(p.get("id", "")),
            }
            for p in values
        ]

    # ---------- Issues ----------
    def get_issue(
        self,
        issue_id: str,
        fields: str = "summary,description,status,assignee,reporter,created,updated,priority,issuetype,project",
    ):
        result = self.get(
            f"issue/{issue_id}", {"fields": fields, "expand": "renderedFields,names"}
        )
        issue_data = {
            "key": issue_id,
            "title": result["fields"]["summary"],
            "status": result["fields"]["status"]["name"],
            "type": result["fields"]["issuetype"]["name"],
            "project": result["fields"]["project"]["name"],
            "priority": result["fields"].get("priority", {}).get("name", "Not set"),
            "created": result["fields"].get("created", "Unknown"),
            "updated": result["fields"].get("updated", "Unknown"),
            "reporter": result["fields"]
            .get("reporter", {})
            .get("displayName", self.username),
            "assignee": result["fields"]
            .get("assignee", {})
            .get("displayName", "Unassigned"),
            "link": f"{self.base_url}/browse/{issue_id}",
        }
        if result.get("renderedFields", {}).get("description"):
            issue_data["description"] = result["renderedFields"]["description"]
        else:
            issue_data["description"] = "<p><em>No description provided</em></p>"
        return issue_data

    def _text_to_adf(self, text: str) -> Dict[str, Any]:
        # Jira Cloud v3 utilise Atlassian Document Format (ADF) pour les commentaires
        return {
            "type": "doc",
            "version": 1,
            "content": [
                {
                    "type": "paragraph",
                    "content": [{"type": "text", "text": text}],
                }
            ],
        }

    def add_comment(self, issue_id: str, comment: Any) -> Dict[str, Any]:
        """
        Add a comment to an issue.

        issue_id: e.g. "MPBS-343"
        comment: plain text string OR an ADF dict (advanced)
        """
        if not issue_id:
            raise ValueError("issue_id is required")

        if isinstance(comment, dict):
            body = comment  # assume already ADF
        else:
            comment_text = (comment or "").strip()
            if not comment_text:
                raise ValueError("comment cannot be empty")
            body = self._text_to_adf(comment_text)

        payload = {"body": body}

        # POST /rest/api/3/issue/{issueIdOrKey}/comment
        result = self.post(f"issue/{issue_id}/comment", payload)

        return {
            "id": result.get("id"),
            "created": result.get("created"),
            "self": result.get("self"),
            "issue_id": issue_id,
        }

    # ---------- JQL helpers ----------
    def _autoquote_jql_values(self, jql: str) -> str:
        def _quote_project(m):
            val = m.group(1).strip()
            if val.startswith(("'", '"')):
                return m.group(0)
            if " " in val or "-" in val:
                return f'project = "{val}"'
            return m.group(0)

        jql = re.sub(
            r'(?i)\bproject\s*=\s*([^"\']+?)(?=\s+(AND|OR)\s+|$)', _quote_project, jql
        )

        def _quote_assignee(m):
            val = m.group(1).strip()
            if val.startswith(("'", '"')):
                return m.group(0)
            if " " in val:
                return f'assignee = "{val}"'
            return m.group(0)

        jql = re.sub(
            r'(?i)\bassignee\s*=\s*([^"\']+?)(?=\s+(AND|OR)\s+|$)', _quote_assignee, jql
        )
        return jql

    def _llm_pick_best_project(
        self, project_names: List[str], user_value: str
    ) -> Optional[str]:
        if not self._use_openai:
            return None
        try:
            prompt = (
                "You are given a user-entered Jira project name and a list of valid Jira project names.\n"
                "Pick the single best matching project name. If none are reasonable, respond exactly: NONE.\n\n"
                f"User value: {user_value}\n"
                f"Choices:\n- "
                + "\n- ".join(project_names)
                + "\n\nAnswer with just the chosen name (or NONE)."
            )
            resp = openai.chat.completions.create(
                model="gpt-4o-mini",
                messages=[{"role": "user", "content": prompt}],
                temperature=0,
            )
            text = (resp.choices[0].message.content or "").strip()
            if text and text.upper() != "NONE" and text in project_names:
                return text
        except Exception:
            return None
        return None

    def _resolve_project_name_to_key(self, user_value: str) -> Optional[str]:
        projects = self.search_projects("", max_results=1000)
        if not projects:
            return None
        names = [p["name"] for p in projects if p.get("name")]
        for p in projects:
            if p["name"].lower() == user_value.lower():
                return p["key"]
        pick = self._llm_pick_best_project(names, user_value)
        if pick:
            match = next((p for p in projects if p["name"] == pick), None)
            return match["key"] if match else None
        close = difflib.get_close_matches(user_value, names, n=1, cutoff=0.6)
        if close:
            chosen_name = close[0]
            match = next((p for p in projects if p["name"] == chosen_name), None)
            if match:
                return match["key"]
        keys = [p["key"] for p in projects if p.get("key")]
        close_key = difflib.get_close_matches(user_value, keys, n=1, cutoff=0.6)
        if close_key:
            return close_key[0]
        return None

    def _rewrite_project_in_jql(self, jql: str) -> str:
        def _replace(m):
            original = m.group(0)
            val = (m.group(1) or m.group(2) or m.group(3) or "").strip()
            if not val:
                return original
            key = self._resolve_project_name_to_key(val)
            return f"project = {key}" if key else original

        return re.sub(
            r"""(?ix)\bproject\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s)]+))""", _replace, jql
        )

    def _rewrite_assignee_in_jql(self, jql: str) -> str:
        def _eq_replacer(match):
            original = match.group(0)
            name = next((g for g in match.groups() if g), "").strip()
            if not name:
                return original
            users = self.search_users(name, max_results=5)
            if users and users[0]["accountId"]:
                return f"assignee = {users[0]['accountId']}"
            return original

        jql = re.sub(
            r"""(?ix)\bassignee\s*=\s*(?:'([^']+)'|"([^"]+)"|([^\s)]+))""",
            _eq_replacer,
            jql,
        )

        def _in_replacer(match):
            original = match.group(0)
            inner = match.group(1)
            names = []
            for raw in inner.split(","):
                s = raw.strip()
                if (s.startswith("'") and s.endswith("'")) or (
                    s.startswith('"') and s.endswith('"')
                ):
                    s = s[1:-1]
                if s:
                    names.append(s)
            ids = []
            for n in names:
                users = self.search_users(n, max_results=5)
                if users and users[0]["accountId"]:
                    ids.append(users[0]["accountId"])
            if ids:
                return f"assignee in ({','.join(ids)})"
            return original

        jql = re.sub(r"(?i)\bassignee\s+in\s*\(([^)]+)\)", _in_replacer, jql)
        return jql

    # ---------- Search ----------
    def search(self, query: str, max_results: int = 10):
        if any(
            op in query for op in ["=", "~", ">", "<", " AND ", " OR ", " ORDER BY "]
        ):
            jql = query
        else:
            terms = query.split()
            jql = (
                " OR ".join([f'text ~ "{t}"' for t in terms])
                if terms
                else f'text ~ "{query}"'
            )
        jql = self._autoquote_jql_values(jql)
        jql = self._rewrite_project_in_jql(jql)
        jql = self._rewrite_assignee_in_jql(jql)

        body = {
            "jql": jql,
            "maxResults": max_results,
            "fields": [
                "summary",
                "status",
                "issuetype",
                "priority",
                "updated",
                "assignee",
            ],
        }
        for ep in ["search/jql", "search"]:
            url = f"{self.base_url}/rest/api/3/{ep}"
            resp = requests.post(
                url, headers=self.headers, json=body, auth=self._get_auth()
            )
            if resp.status_code in (404, 410):
                last_resp = resp
                continue
            data = self._handle_response(resp, f"search via '{ep}' for '{jql}'")
            if "issues" not in data:
                raise JiraApiError(
                    f"Unexpected Jira response — keys present: {list(data.keys())}"
                )
            issues = []
            for item in data["issues"]:
                f = item.get("fields", {})
                assignee = f.get("assignee") or {}
                issues.append(
                    {
                        "key": item.get("key", "Unknown"),
                        "summary": f.get("summary", ""),
                        "status": f.get("status", {}).get("name", ""),
                        "type": f.get("issuetype", {}).get("name", ""),
                        "priority": f.get("priority", {}).get("name", "Not set"),
                        "updated": f.get("updated", "Unknown"),
                        "assignee": assignee.get("displayName", "Unassigned"),
                        "assignee_accountId": assignee.get("accountId", ""),
                        "link": f"{self.base_url}/browse/{item.get('key','')}",
                    }
                )
            return {
                "issues": issues,
                "total": data.get("total", len(issues)),
                "displayed": len(issues),
            }
        raise JiraApiError(
            f"Jira API error ({last_resp.status_code}): {last_resp.text}"
            if "last_resp" in locals()
            else "Jira search failed: no response"
        )


class Tools:
    def __init__(self):
        self.valves = self.Valves()

    class Valves(BaseModel):
        username: str = Field(
            "", description="Your Jira username or email (leave empty if using PAT)"
        )
        password: str = Field(
            "", description="Your Jira password (leave empty if using PAT)"
        )
        pat: str = Field(
            "",
            description="Your Jira Personal Access Token (leave empty if using username/password)",
        )
        base_url: str = Field(
            "",
            description="Your Jira base URL (e.g., https://your-company.atlassian.net)",
        )
        openai_api_key: str = Field(
            "",
            description="OpenAI API key (optional). If provided, improves project-name matching. No base URL needed.",
        )

        @validator("base_url")
        def validate_url(cls, v):
            if not v:
                return v
            if not v.startswith(("http://", "https://")):
                raise ValueError("URL must start with http:// or https://")
            return v

        @validator("pat", always=True)
        def validate_credentials(cls, v, values):
            user = values.get("username") or ""
            pwd = values.get("password") or ""
            if (user or pwd or v) and (not v and not (user and pwd)):
                raise ValueError("Provide PAT, or username + password (API token).")
            return v

    def _get_jira_client(self, __user__: dict = {}):
        """
        Crée un client Jira en essayant d'abord OAuth, puis fallback sur PAT/username+password.
        """
        user_id = __user__.get("id") if isinstance(__user__, dict) else None

        # Essayer OAuth d'abord si disponible
        oauth_token = None
        base_url_from_oauth = None

        if _OAUTH_AVAILABLE and user_id and get_user_oauth_token:
            try:
                token_data = get_user_oauth_token(user_id)
                if token_data:
                    oauth_token = token_data.get("access_token")
                    # Récupérer base_url depuis les ressources accessibles
                    accessible_resources = token_data.get("accessible_resources", [])
                    if accessible_resources and len(accessible_resources) > 0:
                        # Utiliser la première ressource (ou permettre à l'utilisateur de choisir)
                        base_url_from_oauth = accessible_resources[0].get("url", "").rstrip("/")
            except Exception as e:
                # En cas d'erreur, continuer avec les méthodes traditionnelles
                pass

        # Déterminer base_url: OAuth > valves > erreur
        base_url = base_url_from_oauth or self.valves.base_url
        if not base_url:
            raise ValueError(
                "Jira base URL not configured. Please provide your Jira base URL in valves, "
                "or complete OAuth authentication to auto-detect it."
            )

        # Si OAuth est disponible, l'utiliser (pas besoin de credentials)
        if oauth_token:
            return Jira(
                username="",  # Non utilisé avec OAuth
                password="",  # Non utilisé avec OAuth
                base_url=base_url,
                pat="",  # Non utilisé avec OAuth
                openai_api_key=self.valves.openai_api_key,
                oauth_token=oauth_token,
            )

        # Fallback sur les méthodes traditionnelles
        if not self.valves.pat and (
            not self.valves.username or not self.valves.password
        ):
            raise ValueError(
                "Jira credentials not configured. Provide either:\n"
                "1. OAuth authentication (complete OAuth flow via /api/oauth/atlassian/callback), OR\n"
                "2. Username + password (API token), OR\n"
                "3. Personal Access Token (PAT)"
            )

        return Jira(
            self.valves.username,
            self.valves.password,
            base_url,
            self.valves.pat,
            self.valves.openai_api_key,
        )

    # ---- tool methods remain the same as your last version (get_issue, search_issues, create_issue, add_comment, assign_issue, update_status, list_projects, get_issue_metadata) ----

    # -------- Tool methods (unchanged behavior) --------

    async def get_issue(
        self,
        issue_id: str,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        __user__: dict = {},
    ):
        event_emitter = EventEmitter(__event_emitter__)
        try:
            await event_emitter.emit_status(f"Retrieving Jira issue {issue_id}", False)
            jira = self._get_jira_client(__user__)
            issue = jira.get_issue(issue_id)
            issue_card = f"""
### 📩 {issue['key']}: {issue['title']}

**Status:** {issue['status']}  
**Type:** {issue['type']}  
**Priority:** {issue['priority']}  
**Project:** {issue['project']}  

**Created:** {issue['created']}  
**Updated:** {issue['updated']}  
**Reporter:** {issue['reporter']}  
**Assignee:** {issue['assignee']}  

**Link:** [{issue['key']}]({issue['link']})
"""
            await event_emitter.emit_message(issue_card)
            await event_emitter.emit_source(
                f"Description of {issue['key']}",
                issue["link"],
                issue["description"],
                True,
            )

            comments = jira.get_comments(issue_id)
            if comments:
                comment_text = f"### 💬 Comments on {issue_id} ({len(comments)})\n\n"
                for i, comment in enumerate(comments):
                    comment_text += f"**{i+1}. {comment['author']}** - {comment['created']}\n{comment['text']}\n\n"
                await event_emitter.emit_message(comment_text)

            await event_emitter.emit_status(
                f"Successfully retrieved Jira issue {issue_id}", True
            )
            return json.dumps(issue)
        except Exception as e:
            await event_emitter.emit_status(
                f"Failed to get issue {issue_id}: {str(e)}", True, True
            )
            return f"Error: {str(e)}"

    async def search_issues(
        self,
        query: str,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        max_results: int = 10,
        __user__: dict = {},
    ):
        event_emitter = EventEmitter(__event_emitter__)
        try:
            await event_emitter.emit_status(f"Searching Jira for: {query}", False)
            jira = self._get_jira_client(__user__)
            results = jira.search(query, max_results)
            if not results["issues"]:
                await event_emitter.emit_status(
                    f"No issues found matching: {query}", True
                )
                return json.dumps({"message": "No issues found", "total": 0})

            headers = [
                "Key",
                "Summary",
                "Status",
                "Type",
                "Priority",
                "Updated",
                "Assignee",
            ]
            rows = []
            for issue in results["issues"]:
                rows.append(
                    [
                        f"[{issue['key']}]({issue['link']})",
                        issue["summary"],
                        issue["status"],
                        issue["type"],
                        issue["priority"],
                        issue["updated"],
                        issue.get("assignee", "Unassigned"),
                    ]
                )
            await event_emitter.emit_table(
                headers,
                rows,
                f"Found {results['total']} issues (showing {results['displayed']})",
            )
            await event_emitter.emit_status(
                f"Found {results['total']} issues matching your query", True
            )
            return json.dumps(results)
        except Exception as e:
            await event_emitter.emit_status(
                f"Failed to search issues: {str(e)}", True, True
            )
            return f"Error: {str(e)}"

